WITH m AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, DATE_TRUNC('month',BULAN)::DATE mo, SUM(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',HEKTAR,0)) ha, SUM(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',COALESCE(JML_POKOK,0),0)) pk FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2027-01-01' GROUP BY 1,2,3) SELECT ba, afd, ROUND(AVG(IFF(mo<'2026-10-01',ha,NULL)),2) ha_ytd, ROUND(AVG(IFF(mo<'2026-10-01',pk,NULL))) pokok_ytd, ROUND(AVG(ha),2) ha_fy, ROUND(AVG(pk)) pokok_fy FROM m GROUP BY 1,2 ORDER BY 1,2